def simplify(op, a, b):
    if op == "add" and b == 0: return ("identity", a)
    if op == "mul" and b == 1: return ("identity", a)
    if op == "mul" and b == 0: return ("const", 0)
    return (op, a, b)
graph = [("add", "x", 0), ("mul", "y", 1), ("mul", "z", 0), ("add", "w", 5)]
print([simplify(*n) for n in graph])

layers = {"conv1": 0.2, "conv2": 0.4, "fc1": 2.1, "fc2": 1.8}
budget = 1.0
plan = {k: ("int8" if v < budget else "fp32") for k, v in layers.items()}
print("accuracy loss per layer:", layers)
print("precision plan:", plan)
print("quantized layers:", sum(1 for v in plan.values() if v == "int8"), "of", len(plan))

live = {"a": (0, 3), "b": (1, 2), "c": (2, 5), "d": (4, 6)}
bufs, assign = [], {}
for t, (s, e) in sorted(live.items(), key=lambda x: x[1][0]):
    placed = False
    for i, (bs, be) in enumerate(bufs):
        if e <= bs or s >= be:
            bufs[i] = (min(bs, s), max(be, e)); assign[t] = i; placed = True; break
    if not placed:
        bufs.append((s, e)); assign[t] = len(bufs) - 1
print("tensors:", len(live), "buffers used:", len(bufs))
print("assignment:", assign)

buckets = [1, 4, 16, 64]
def dispatch(n):
    for b in buckets:
        if n <= b: return b
    return buckets[-1]
for n in [1, 3, 7, 20, 63, 200]:
    print("seq_len", n, "-> compiled variant", dispatch(n))

uses = {"out": ["a", "b"], "a": ["x"], "b": [], "dead1": ["dead2"], "dead2": []}
live, stack = set(), ["out"]
while stack:
    n = stack.pop()
    if n not in live:
        live.add(n); stack.extend(uses.get(n, []))
print("live nodes:", sorted(live))
print("removed:", sorted(set(uses) - live))
